#!/usr/bin/env python3
"""rtlgen: generate rtl/common from its descriptions.

    rtlgen.py --desc rtl/common --out build/rtl/common --versions v1[,v2...]

Reads cpuid.toml, reset.toml, platform.toml and pins.toml and writes, into
--out (the build tree; generated files are not kept in git):

    vibe86_cpuid_pkg.sv     cpuid_<version>(leaf, subleaf) -> {EDX,ECX,EBX,EAX}
    vibe86_reset_pkg.sv     RESET_<REG>, RESET_GPR[16], RESET_SEG_*[8]
    vibe86_reset_apply.svh  sp[SP_<REG>] <= RESET_<REG> for each register but
                            RIP/RFLAGS (a core without SP_<REG> fails to build:
                            the description and the core can't drift apart)
    vibe86_platform_pkg.sv  PLAT_<SECTION>_<KEY>, MSR_<NAME>_ADDR/_DEFAULT
    vibe86_die_pkg.sv       DIE_<PIN>_W
    vibe86_die_ports.svh    the die's port list, included by each core module
    vibe86_platform.h       the platform constants for vsim (C)
    vibe86_die.h            the die's pins for vsim (C++), die_in()/die_out()

A file is rewritten only when its contents change, so the Verilator build
isn't redone for nothing.
"""

import argparse
import os
import sys
import tomllib

REGS = ("eax", "ebx", "ecx", "edx")
SEG_ORDER = ("ES", "CS", "SS", "DS", "FS", "GS", "LDTR", "TR")
HEADER = "generated by tools/gen/rtlgen.py from rtl/common/{src}: do not edit"


def die(msg):
    sys.exit(f"rtlgen: {msg}")


def vnum(v):
    if not (v.startswith("v") and v[1:].isdigit()):
        die(f"bad core version '{v}'")
    return int(v[1:])


def write(path, text):
    old = None
    if os.path.exists(path):
        with open(path) as f:
            old = f.read()
    if old != text:
        with open(path, "w") as f:
            f.write(text)


def sv_hex(v, w=64):
    return f"{w}'h{v:0{(w + 3) // 4}X}"


# ---------------------------------------------------------------------------
# CPUID

def str_regs(s, n):
    """n little-endian dwords of the ASCII string s (zero-padded)."""
    b = s.encode("ascii")
    if len(b) > 4 * n:
        die(f"string '{s}' longer than {4 * n} bytes")
    b = b.ljust(4 * n, b"\0")
    return [int.from_bytes(b[4 * i:4 * i + 4], "little") for i in range(n)]


def signature(ident):
    fam, model, step = ident["family"], ident["model"], ident["stepping"]
    base_fam = min(fam, 0xF)
    ext_fam = fam - 0xF if fam >= 0xF else 0
    return (ext_fam << 20) | ((model >> 4) << 16) | (base_fam << 8) | ((model & 0xF) << 4) | step


def cpuid_table(c, version, plat):
    """{(leaf, sub or None): [eax, ebx, ecx, edx]} for a core version."""
    ident = c["identity"]
    t = {}

    def at(leaf, sub=None):
        return t.setdefault((leaf, sub), [0, 0, 0, 0])

    for lf in c.get("leaf", []):
        r = at(lf["leaf"], lf.get("sub"))
        for i, reg in enumerate(REGS):
            r[i] |= lf.get(reg, 0)
    sig = signature(ident)
    v_ebx, v_edx, v_ecx = str_regs(ident["vendor"], 3)
    if len(ident["vendor"]) != 12:
        die("the vendor string must be 12 characters")
    r = at(1)
    r[0] = sig
    r[1] |= (ident["clflush_line"] // 8) << 8 | 1 << 16
    for f in c["feature"]:
        leaf, sub = f["leaf"], f.get("sub")
        if leaf in (0x7, 0xD) and sub is None:
            sub = 0
        r = at(leaf, sub)
        since = f.get("since")
        if since is not None and vnum(since) <= vnum(version):
            r[REGS.index(f["reg"])] |= 1 << f["bit"]
    # sub-leaf leaves: every (leaf, sub) present; a leaf without one never is
    basic = [l for l, _ in t if l < 0x8000_0000]
    max_basic = max(basic + [1])
    at(0)[:] = [max_basic, v_ebx, v_ecx, v_edx]
    brand = str_regs(ident["brand"], 12)
    for i in range(3):
        at(0x8000_0002 + i)[:] = brand[4 * i:4 * i + 4]
    r = at(0x8000_0001)
    r[0] = sig
    r = at(0x8000_0008)
    r[0] = ident["phys_addr_bits"] | ident["lin_addr_bits"] << 8
    ext = [l for l, _ in t if l >= 0x8000_0000]
    at(0x8000_0000)[:] = [max(ext), v_ebx, v_ecx, v_edx]
    return t


def gen_cpuid(c, versions, plat):
    out = [f"// {HEADER.format(src='cpuid.toml')}",
           "//",
           f"// Vendor \"{c['identity']['vendor']}\", family {c['identity']['family']:X}h, "
           f"model {c['identity']['model']:X}h, stepping {c['identity']['stepping']}.",
           "// Dynamic fields the core ORs in: CPUID.1:EBX[31:24] (APIC ID),",
           "// CPUID.1:ECX[27] (OSXSAVE = CR4.OSXSAVE).",
           "package vibe86_cpuid_pkg;",
           f"  localparam logic [31:0] CPUID_SIGNATURE = {sv_hex(signature(c['identity']), 32)};",
           ""]
    for f in c["feature"]:
        out.append(f"  localparam int CPUID_BIT_{f['name'].upper()} = {f['bit']};   "
                   f"// leaf {f['leaf']:X}h.{f.get('sub', 0)} {f['reg'].upper()}"
                   f"{' (verify)' if f.get('verify') else ''}"
                   f"{'' if f.get('since') else ' -- not implemented yet'}")
    for v in versions:
        t = cpuid_table(c, v, plat)
        out += ["",
                f"  // core version {v}: leaves above the maximum and unknown leaves return 0",
                f"  // (vibe86 behaviour; Intel returns the highest basic leaf's data)",
                f"  function automatic logic [127:0] cpuid_{v}(input logic [31:0] leaf, "
                "input logic [31:0] sub);",
                "    logic [127:0] r;",
                "    r = '0;",
                "    case (leaf)"]
        leaves = sorted({l for l, _ in t})
        for leaf in leaves:
            subs = sorted((s for l, s in t if l == leaf), key=lambda s: -1 if s is None else s)

            def val(regs):
                eax, ebx, ecx, edx = regs
                return f"{{32'h{edx:08X}, 32'h{ecx:08X}, 32'h{ebx:08X}, 32'h{eax:08X}}}"
            if subs == [None]:
                out.append(f"      32'h{leaf:08X}: r = {val(t[(leaf, None)])};")
            else:
                out.append(f"      32'h{leaf:08X}:")
                out.append("        case (sub)")
                for s in subs:
                    out.append(f"          32'd{s}: r = {val(t[(leaf, s)])};")
                out.append("          default: r = '0;")
                out.append("        endcase")
        out += ["      default: r = '0;",
                "    endcase",
                "    return r;",
                "  endfunction"]
    out += ["endpackage", ""]
    return "\n".join(out)


# ---------------------------------------------------------------------------
# reset state

def resolve(v, c, plat, what):
    if isinstance(v, int):
        return v
    if v == "cpuid.signature":
        return signature(c["identity"])
    if isinstance(v, str) and v.startswith("msr."):
        m = plat["msr"].get(v[4:])
        if m is None:
            die(f"{what}: no MSR {v[4:]} in platform.toml")
        return m["default"]
    die(f"{what}: can't resolve {v!r}")


def gen_reset(r, c, plat):
    out = [f"// {HEADER.format(src='reset.toml')}",
           "// Intel SDM Vol. 3A Table 10-1; AMD APM Vol. 2 Table 14-1.",
           "package vibe86_reset_pkg;"]
    gpr = [0] * 16
    names = ["RAX", "RCX", "RDX", "RBX", "RSP", "RBP", "RSI", "RDI"] + [f"R{i}" for i in range(8, 16)]
    for k, v in r.get("gpr", {}).items():
        if k not in names:
            die(f"reset.toml: unknown GPR {k}")
        gpr[names.index(k)] = resolve(v, c, plat, f"gpr.{k}")
    out.append("  localparam logic [63:0] RESET_GPR [16] = '{"
               + ", ".join(sv_hex(x) for x in gpr) + "};")
    for k, v in r["registers"].items():
        out.append(f"  localparam logic [63:0] RESET_{k} = {sv_hex(resolve(v, c, plat, k))};")
    segs = r["segments"]
    if set(segs) != set(SEG_ORDER):
        die("reset.toml: [segments] must list " + " ".join(SEG_ORDER))
    out.append("  // segment registers, in the order " + " ".join(SEG_ORDER))
    for part in ("sel", "base", "limit", "attr"):
        out.append(f"  localparam logic [63:0] RESET_SEG_{part.upper()} [8] = '{{"
                   + ", ".join(sv_hex(segs[s][part]) for s in SEG_ORDER) + "};")
    out += ["endpackage", ""]
    return "\n".join(out)


# ---------------------------------------------------------------------------
# platform constants

def plat_consts(plat):
    """[(name, value, comment)] of the scalar constants."""
    out = []
    for sec, kv in plat.items():
        if sec == "msr":
            continue
        for k, v in kv.items():
            if isinstance(v, bool):
                v = int(v)
            if isinstance(v, int):
                out.append((f"PLAT_{sec.upper()}_{k.upper()}", v))
    return out


def gen_platform_sv(plat):
    out = [f"// {HEADER.format(src='platform.toml')}",
           "package vibe86_platform_pkg;"]
    for n, v in plat_consts(plat):
        out.append(f"  localparam logic [63:0] {n} = {sv_hex(v)};")
    for n, m in plat["msr"].items():
        out.append(f"  localparam logic [31:0] MSR_{n}_ADDR = {sv_hex(m['addr'], 32)};")
        out.append(f"  localparam logic [63:0] MSR_{n}_DEFAULT = {sv_hex(m['default'])};")
    out += ["endpackage", ""]
    return "\n".join(out)


def gen_platform_h(plat):
    out = [f"/* {HEADER.format(src='platform.toml')} */",
           "#ifndef VIBE86_PLATFORM_H", "#define VIBE86_PLATFORM_H", ""]
    for n, v in plat_consts(plat):
        out.append(f"#define {n}\t0x{v:X}ull")
    out.append("")
    for n, m in plat["msr"].items():
        out.append(f"#define MSR_{n}_ADDR\t0x{m['addr']:X}u")
        out.append(f"#define MSR_{n}_DEFAULT\t0x{m['default']:X}ull")
    out += ["", "#endif", ""]
    return "\n".join(out)


# ---------------------------------------------------------------------------
# die interface

def ctype(p):
    w = p["width"]
    if p.get("ctype") == "bytes":
        return "uint8_t", f"[{w // 8}]"
    if w == 1:
        return "bool", ""
    if w <= 32:
        return "uint32_t", ""
    if w <= 64:
        return "uint64_t", ""
    if w % 32:
        die(f"pin {p['name']}: a wide pin must be a multiple of 32 bits")
    return "uint32_t", f"[{w // 32}]"


def gen_die_sv(pins):
    pkg = [f"// {HEADER.format(src='pins.toml')}",
           "package vibe86_die_pkg;"]
    for p in pins:
        pkg.append(f"  localparam int DIE_{p['name'].upper()}_W = {p['width']};   // {p['desc']}")
    pkg += ["endpackage", ""]
    ports = [f"// {HEADER.format(src='pins.toml')}",
             "// The die interface: `include it as a core module's port list."]
    for i, p in enumerate(pins):
        rng = "" if p["width"] == 1 else f"[{p['width'] - 1}:0] "
        d = "input " if p["dir"] == "in" else "output"
        comma = "," if i < len(pins) - 1 else ""
        ports.append(f"  {d} logic {rng}{p['name']}{comma}".ljust(44) + f"// {p['desc']}")
    ports.append("")
    return "\n".join(pkg), "\n".join(ports)


def gen_die_h(pins, structs, maxcores):
    out = [f"/* {HEADER.format(src='pins.toml')} */",
           "/*",
           " * The die's pins as vsim sees them (struct die_pins, the base of",
           " * struct cpu in sim/cpu.h), and the copy to and from a Verilated model",
           " * of one core: die_in(pins, model, core), die_out(pins, model, core).",
           " */",
           "#ifndef VIBE86_DIE_H", "#define VIBE86_DIE_H", "",
           "#include <cstdint>", "",
           "struct die_pins {",
           f"\tstatic constexpr unsigned MAXCORES = {maxcores};", ""]
    groups = {}
    for p in pins:
        c = p.get("c", p["name"])
        if "[]." in c:
            g, m = c.split("[].")
            groups.setdefault(g, []).append((m, p))
    for g, mem in groups.items():
        if g not in structs:
            die(f"pins.toml: no [structs] entry for '{g}'")
        out.append(f"\tstruct {structs[g]} {{")
        for m, p in mem:
            t, a = ctype(p)
            out.append(f"\t\t{t} {m}{a};\t/* {p['desc']} */")
        out.append("\t};")
    out.append("")
    routes = []
    for p in pins:
        c = p.get("c", p["name"])
        t, a = ctype(p)
        if "[]." in c:
            continue
        if c.endswith("[]"):
            out.append(f"\t{t} {c[:-2]}[MAXCORES]{a} = {{}};\t/* per core: {p['desc']} */")
        else:
            out.append(f"\t{t} {c}{a} = {{}};\t/* {p['dir']}: {p['desc']} */")
        if p.get("route"):
            routes.append(p["route"])
    for g in groups:
        out.append(f"\t{structs[g]} {g}[MAXCORES] = {{}};")
    for r in routes:
        out.append(f"\tunsigned {r} = 0;\t/* the core the routed input above goes to */")
    out += ["};", ""]

    def words(p):
        return p["width"] // 32

    out += ["/* inputs: pins -> one core's model */",
            "template <class M>",
            "static inline void die_in(const die_pins &p, M &m, unsigned core)",
            "{",
            "\t(void)core;"]
    for p in pins:
        if p["dir"] != "in":
            continue
        n = p["name"]
        c = p.get("c", n)
        if p["width"] > 64:
            out.append(f"\tfor (unsigned i = 0; i < {words(p)}; i++) m.{n}[i] = p.{c}[i];")
        elif p.get("route"):
            out.append(f"\tm.{n} = p.{c} && p.{p['route']} == core;")
        else:
            mask = "" if p["width"] in (1, 64) else f" & 0x{(1 << p['width']) - 1:X}u"
            out.append(f"\tm.{n} = p.{c}{mask};")
    out += ["}", "",
            "/* outputs: one core's model -> pins */",
            "template <class M>",
            "static inline void die_out(die_pins &p, const M &m, unsigned core)",
            "{",
            "\t(void)core;"]
    for p in pins:
        if p["dir"] != "out":
            continue
        n = p["name"]
        c = p.get("c", n)
        if "[]." in c:
            g, mem = c.split("[].")
            dst = f"p.{g}[core].{mem}"
        elif c.endswith("[]"):
            dst = f"p.{c[:-2]}[core]"
        else:
            dst = f"p.{c}"
        if p.get("ctype") == "bytes":
            out.append(f"\tfor (unsigned i = 0; i < {p['width'] // 8}; i++)")
            out.append(f"\t\t{dst}[i] = (uint8_t)(m.{n}[i / 4] >> (8 * (i % 4)));")
        elif p["width"] > 64:
            out.append(f"\tfor (unsigned i = 0; i < {words(p)}; i++) {dst}[i] = m.{n}[i];")
        else:
            out.append(f"\t{dst} = m.{n};")
    out += ["}", "", "#endif", ""]
    return "\n".join(out)


# ---------------------------------------------------------------------------

def main():
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--desc", required=True, help="rtl/common (the descriptions)")
    ap.add_argument("--out", required=True)
    ap.add_argument("--versions", required=True, help="core versions, comma-separated")
    a = ap.parse_args()

    def load(n):
        with open(os.path.join(a.desc, n), "rb") as f:
            return tomllib.load(f)
    c, r, plat, pins = load("cpuid.toml"), load("reset.toml"), load("platform.toml"), load("pins.toml")
    versions = [v for v in a.versions.split(",") if v]
    for v in versions:
        vnum(v)
    for f in c["feature"]:
        if f.get("since"):
            vnum(f["since"])
    seen = set()
    for f in c["feature"]:
        k = (f["leaf"], f.get("sub", 0), f["reg"], f["bit"])
        if k in seen:
            die(f"cpuid.toml: two features at leaf {f['leaf']:X}h {f['reg']} bit {f['bit']}")
        seen.add(k)
    os.makedirs(a.out, exist_ok=True)
    o = lambda n: os.path.join(a.out, n)
    write(o("vibe86_cpuid_pkg.sv"), gen_cpuid(c, versions, plat))
    write(o("vibe86_reset_pkg.sv"), gen_reset(r, c, plat))
    write(o("vibe86_reset_apply.svh"), "\n".join(
        [f"// {HEADER.format(src='reset.toml')}"] +
        [f"    sp[SP_{k}[7:0]] <= RESET_{k};" for k in r["registers"] if k not in ("RIP", "RFLAGS")]) + "\n")
    write(o("vibe86_platform_pkg.sv"), gen_platform_sv(plat))
    write(o("vibe86_platform.h"), gen_platform_h(plat))
    pkg, ports = gen_die_sv(pins["pin"])
    write(o("vibe86_die_pkg.sv"), pkg)
    write(o("vibe86_die_ports.svh"), ports)
    write(o("vibe86_die.h"), gen_die_h(pins["pin"], pins.get("structs", {}),
                                       plat["socket"]["max_cores"]))
    return 0


if __name__ == "__main__":
    sys.exit(main())
